    adcs_vec3_t b_unit;
    adcs_vec3_t p_unit;
    double dot_val;
    double c;
    adcs_vec3_t cross_res;
    double norm_cross;
    size_t i, j;
    int matrix_finite = 1;

    if ((c_bi == NULL) || (check_body == NULL) || (check_inertial == NULL) || 
        (angle_residual_rad == NULL) || (cross_residual_body == NULL)) {
        return ADCS_E_NULL;
    }

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (!isfinite(c_bi->m[i][j])) {
                matrix_finite = 0;
                break;
            }
        }
        if (!matrix_finite) break;
    }
    if (!matrix_finite) {
        *angle_residual_rad = INFINITY;
        *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_NOT_FINITE;
    }

    if (!adcs_is_finite_vec3(check_body) || !adcs_is_finite_vec3(check_inertial)) {
        *angle_residual_rad = INFINITY;
        *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_NOT_FINITE;
    }

    p_mapped = adcs_mat3_mul_vec(c_bi, check_inertial);

    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &b_unit) != ADCS_OK) {
        *angle_residual_rad = INFINITY;
        *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(&p_mapped, ADCS_EPS_NORM, &p_unit) != ADCS_OK) {
        *angle_residual_rad = INFINITY;
        *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_RANGE;
    }

    dot_val = adcs_vec3_dot(&b_unit, &p_unit);
    c = ((dot_val < -1.0) ? -1.0 : ((dot_val > 1.0) ? 1.0 : dot_val));

    cross_res = adcs_vec3_cross(&b_unit, &p_unit);

    norm_cross = adcs_vec3_norm(&cross_res);
    *angle_residual_rad = atan2(norm_cross, c);

    *cross_residual_body = cross_res;

    return ADCS_OK;
}

