    adcs_vec3_t p, b, pb_normed;
    double dot, cross_norm, angle;
    adcs_vec3_t cross_vec;
    size_t i, j;

    /* 1. Null checks */
    if ((c_bi == NULL) || (check_body == NULL) || (check_inertial == NULL) ||
        (angle_residual_rad == NULL) || (cross_residual_body == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Default failure values initialization */
    *angle_residual_rad = INFINITY;
    cross_residual_body->x = 0.0;
    cross_residual_body->y = 0.0;
    cross_residual_body->z = 0.0;

    /* 3. Finite checks for matrix */
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (!isfinite(c_bi->m[i][j])) {
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    /* 4. Finite checks for input vectors */
    if (!adcs_is_finite_vec3(check_body) || !adcs_is_finite_vec3(check_inertial)) {
        return ADCS_E_NOT_FINITE;
    }

    /* 5. Map check_inertial to body frame: p = C_BI * check_inertial */
    p = adcs_mat3_mul_vec(c_bi, check_inertial);

    /* 6. Normalize check_body to get b */
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &b) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    /* 7. Normalize mapped vector p to get unit(p) */
    if (adcs_vec3_normalize(&p, ADCS_EPS_NORM, &pb_normed) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    /* 8. Compute dot product and clamp */
    dot = adcs_vec3_dot(&b, &pb_normed);
    dot = ADCS_CLAMP(dot, -1.0, 1.0);

    /* 9. Compute cross product */
    cross_vec = adcs_vec3_cross(&b, &pb_normed);

    /* 10. Compute cross norm */
    cross_norm = adcs_vec3_norm(&cross_vec);

    /* 11. Compute angle residual */
    angle = atan2(cross_norm, dot);

    /* 12. Assign outputs */
    *angle_residual_rad = angle;
    *cross_residual_body = cross_vec;

    return ADCS_OK;
}

